function applyViewShift() {
  const w = window.innerWidth || 1;
  const h = window.innerHeight || 1;
  if (Math.abs(viewShift) < 0.5) {
    camera.clearViewOffset();
  } else {
    // Shift the frustum so the car sits inside the open stage above the
